import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"系统设置","description":"","frontmatter":{},"headers":[],"relativePath":"backend/settings.md","filePath":"backend/settings.md","lastUpdated":1795293416000}`),a={name:`backend/settings.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to “系统设置”">​</a></h1><p>本页说明参数配置、字典与业务编号，适用于后端开发者与运营配置人员。</p><p>Settings 包（Tier 2）提供参数配置、字典与业务编号三类「运行时可调」的数据，并通过 <code>Contracts</code> 的 <code>IConfigValueReader</code> 与 <code>INumberGenerator</code> 供其他包使用。三类都是平台库实体、实现 <code>IOwnedByTenant</code>：平台一份，租户可以有自己的；读共享，写只在本侧。</p><div class="tip custom-block"><p class="custom-block-title">和 appsettings 的区别</p><p><code>appsettings.json</code> 的 <code>BasicApp:*</code> 是部署配置（改了要重启，见<a href="./../configuration">配置参考</a>）；本页的参数是运营配置，存在库里、后台改了即生效，租户可以覆盖。</p></div><h2 id="参数配置" tabindex="-1">参数配置 <a class="header-anchor" href="#参数配置" aria-label="Permalink to “参数配置”">​</a></h2><p><code>SysConfig</code>：键、名称、分组、值、缺省值、数据类型、是否加密、是否内置、是否允许租户覆盖、状态、排序、说明。</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>键</td><td>3–128 位，创建后不可改；本侧唯一</td></tr><tr><td>数据类型</td><td><code>Text</code>、<code>Number</code>、<code>Boolean</code>、<code>Json</code>、<code>Array</code>，按类型校验值与缺省值</td></tr><tr><td>加密</td><td>值经 <code>ISecretProtector</code> 加密存放，不回显（<code>value</code> 为空、<code>hasValue</code> 标出）；更新时留空即保留原值；开关加密会就地加密或解密现值</td></tr><tr><td>租户覆盖</td><td>租户新建与平台参数同键的参数即覆盖它；平台参数 <code>allowTenantOverride = false</code> 时拒绝</td></tr><tr><td>生效值</td><td><code>IConfigValueReader</code>：只看启用的参数 → 当前租户的同键参数优先、其次平台的 → 值为空回落缺省值 → 加密值解密后返回</td></tr></tbody></table><p>操作 <code>configs.create / get / list / update / delete</code>，权限 <code>settings.configs.*</code>（两侧）；内置参数不可删，也不能改数据类型。</p><h3 id="内建参数" tabindex="-1">内建参数 <a class="header-anchor" href="#内建参数" aria-label="Permalink to “内建参数”">​</a></h3><p>读参数的包在 <code>Configure</code> 里 <code>AddConfigCatalog</code> 登记 <code>ConfigDescriptor</code>（键的首段是包名），种子 <code>settings.configs</code> 据此写成平台的内建参数：名称、分组、数据类型、缺省值、是否允许租户覆盖、是否加密与说明每次对齐（没变不写，加密与否变了即就地加密或解密现值），值、状态与排序号只首写、之后归运营；值留空，生效值即缺省值。运营先手建了同键的平台参数即收为内建，但它现有的值不符合登记的数据类型时种子报 <code>SETTINGS_VALIDATION_002</code>（消息带参数键）、不改它，要由人把值改对。下表的参数都由种子建好，在参数配置页直接改值；数据类型固定，JSON 与数组类型的值保存时即校验。</p><h3 id="代码读取的参数" tabindex="-1">代码读取的参数 <a class="header-anchor" href="#代码读取的参数" aria-label="Permalink to “代码读取的参数”">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>谁读</th><th>类型</th><th>含义</th></tr></thead><tbody><tr><td><code>identity.login-methods</code></td><td>Identity</td><td>数组</td><td>登录页开放的方式（只认平台的，不许租户覆盖）：<code>password</code>、<code>email</code>、<code>phone</code>、<code>passkey</code>（还要宿主配了 <code>XiHan:Security:WebAuthn</code>）；缺省 <code>[&quot;password&quot;]</code> 即只有密码登录，写错即登录配置报错</td></tr><tr><td><code>settings.site</code></td><td>Settings</td><td>JSON</td><td>站点设置（允许租户覆盖：租户的同键参数是它的品牌，只写要改的字段）：缺省系统名 <code>XiHan.BasicApp</code>、版权方 <code>XiHanFun</code>，写错的值保存时即拒绝，见下文<a href="#站点设置与租户品牌">站点设置与租户品牌</a></td></tr><tr><td><code>identity.password</code></td><td>Identity</td><td>JSON</td><td>密码策略（只认平台的）：最短长度、须含的字符、历史深度、有效天数与强制改密，写错的值保存时即拒绝，见<a href="./authentication#密码策略">统一认证</a></td></tr><tr><td><code>identity.impersonation</code></td><td>Identity</td><td>JSON</td><td>模仿登录（租户可覆盖）：<code>sessionMinutes</code> 缺省 30、<code>notifyTarget</code> 缺省 <code>true</code>；写错即不能发起，见<a href="./authentication#模仿登录">统一认证</a></td></tr><tr><td><code>access.security.login-auto-ban</code></td><td>Access</td><td>JSON</td><td>登录失败自动封禁（只认平台的，缺省关闭），见<a href="./access-policy">访问策略</a></td></tr><tr><td><code>auditing.retention-days</code></td><td>Auditing</td><td>数字</td><td>日志保留天数（1–3650，只认平台的）；不给缺省值，为空即配置项 <code>BasicApp:Auditing:DefaultRetentionDays</code>（缺省 180）</td></tr><tr><td><code>notification.telegram</code></td><td>Notification</td><td>JSON</td><td>Telegram 的总开关、Webhook 根地址、刷新周期、兜底回复与网络设置（只认平台的，缺省关）</td></tr><tr><td><code>notification.telegram.webhook-secret-token</code></td><td>Notification</td><td>文本（加密）</td><td>Telegram Webhook 密钥（只认平台的）</td></tr><tr><td><code>notification.retention-days</code></td><td>Notification</td><td>数字</td><td>消息记录保留天数（1–3650，缺省 180，只认平台的）：作业 <code>notification.messages.cleanup</code> 删掉更早的、已结束的邮件、短信与机器人消息记录、Telegram 出站审计，以及系统投递的站内通知连同收件箱条目（管理员发的通知公告不删）；写错即清理失败</td></tr><tr><td><code>chat.policy</code></td><td>Chat</td><td>JSON</td><td>聊天策略（Chat 模块开着才有，敏感词租户可覆盖）：<code>retentionDays</code>（消息与通话记录的保留天数，1–3650，缺省 365）与 <code>sensitiveWords</code>；写错即失败，不按错误的值删数据或放过敏感词</td></tr></tbody></table><h2 id="字典" tabindex="-1">字典 <a class="header-anchor" href="#字典" aria-label="Permalink to “字典”">​</a></h2><p><code>SysDict</code> + <code>SysDictItem</code>：字典码、名称、状态；字典项是同一字典内无环的树，带值、标签、排序、缺省项（字典内唯一，设新的即清掉旧的）与 JSON 元数据。</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>字典码</td><td>创建后不可改；平台新建要求全库无同码，租户新建要求平台与本租户都无同码（字典不覆盖）</td></tr><tr><td>可见性</td><td>读共享：平台字典 + 本租户字典；租户改不了平台字典</td></tr><tr><td>停用</td><td>停用的字典不再出现在下拉选项里</td></tr><tr><td>内建</td><td>各包登记的字典，不能删，登记的项也不能删（<code>SETTINGS_CONFLICT_006</code>）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>dicts.create / get / list / update / delete</code></td><td><code>settings.dicts.*</code></td><td>管理字典</td></tr><tr><td><code>dict-items.create / get / list / tree / update / delete</code></td><td><code>settings.dict-items.*</code></td><td>管理字典项</td></tr><tr><td><code>dicts.options</code></td><td>登录即可</td><td>业务表单的下拉（<code>GET /api/dicts:options?code=</code>）</td></tr></tbody></table><p><code>dict-items.list</code> 分页检索字典项（按 <code>dictId</code> 筛选某本字典，关键字匹配编码、名称与附加值），<code>dict-items.tree</code> 一次取整本字典的项（深度优先、带层级，同级按排序号再按编码，给上级选择与级联取值用）。<code>dicts.list / get / options</code> 与 <code>dict-items.list / tree</code> 也是 MCP / AI 工具。前端 SchemaPage 的字典列与壳层的 <code>dictApi.options</code> 都接在 <code>dicts.options</code> 上。</p><h3 id="内建字典" tabindex="-1">内建字典 <a class="header-anchor" href="#内建字典" aria-label="Permalink to “内建字典”">​</a></h3><p>业务按编码依赖某本字典的包在 <code>Configure</code> 里 <code>AddDictCatalog</code> 登记 <code>DictDescriptor</code>（编码的首段是包名，项的上级排在下级前面、缺省项至多一个），种子 <code>settings.dicts</code> 据此写成平台的内建字典：字典的名称、分类、说明与登记的项（名称、附加值、上级）每次对齐，没变不写；状态、排序号与缺省项只首写，之后归运营；运营另加的项不动，照常可删。运营先手建了同码的平台字典即收为内建；租户已有同码的字典时种子报 <code>SETTINGS_CONFLICT_002</code>、不改它，要由人处理。目前没有包登记内建字典。</p><p>演示字典由种子 <code>settings.demo</code> 在演示开关打开时写入，不是内建的。</p><h2 id="业务编号" tabindex="-1">业务编号 <a class="header-anchor" href="#业务编号" aria-label="Permalink to “业务编号”">​</a></h2><p><code>SysNumberingRule</code> + <code>SysNumberingAllocation</code>：编码、前缀、分隔符、日期格式（<code>None</code>、<code>Yyyy</code>、<code>YyyyMM</code>、<code>YyyyMMdd</code>、<code>YyMM</code>、<code>YyMMdd</code>、<code>MMdd</code>）、流水长度、重置周期（<code>Never</code>、<code>Daily</code>、<code>Monthly</code>、<code>Yearly</code>）、时区（缺省 <code>UTC</code>）。</p><ul><li>发号在独立的作用域与事务里完成（<code>StoreScope</code>），号一经发出永久消耗、外层调用失败也不回收、允许空洞；先对规则行加锁更新，同一规则的发号由此串行，并发发号不重复。</li><li>幂等键：同一幂等键参数相同即重放（<code>isReplay</code>），不同即 <code>SETTINGS_CONFLICT_013</code>。</li><li>日期格式要能区分重置周期，时区要能解析，流水位数要装得下已发出的流水值。</li><li>租户看得见自己的规则与平台标为「供租户使用」的规则，只能改自己的；编码在所属一侧内唯一。</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>numbering-rules.create / get / list / update / delete</code></td><td><code>settings.numbering-rules.*</code></td><td></td></tr><tr><td><code>numbering-rules.preview</code></td><td><code>settings.numbering-rules.read</code></td><td>按格式在当前时刻拼出号码，不读库、不发号</td></tr><tr><td><code>numbering-rules.generate</code></td><td><code>settings.numbering-rules.generate</code></td><td>发号（也可由其他包经 <code>INumberGenerator</code> 调用）</td></tr><tr><td><code>numbering-rules.allocations</code></td><td><code>settings.numbering-rules.read</code></td><td>发号记录</td></tr><tr><td><code>numbering-rules.reset</code></td><td><code>settings.numbering-rules.reset</code></td><td>重置流水，理由必填（进操作审计）</td></tr></tbody></table><h2 id="站点设置与租户品牌" tabindex="-1">站点设置与租户品牌 <a class="header-anchor" href="#站点设置与租户品牌" aria-label="Permalink to “站点设置与租户品牌”">​</a></h2><p>站点名、Logo、浏览器图标、登录页（标语与说明）与页脚（版权方、链接、起始年份、备案号与链接）存在系统参数 <code>settings.site</code>：平台的是站点设置，租户的同键参数是它的品牌，只写要改的字段，没写的沿用平台的；文字为空即前端用界面自带的文案。</p><table tabindex="0"><thead><tr><th>操作 / 端点</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>site.get</code>（<code>GET /api/site</code>）</td><td><code>settings.site.read</code></td><td>设置页用：平台取站点设置，租户取自己的品牌（<code>own</code>）与沿用的平台设置（<code>inherited</code>）</td></tr><tr><td><code>site.update</code>（<code>PUT /api/site</code>）</td><td><code>settings.site.update</code></td><td>整体覆盖调用方这一侧；图片只能保留现在的或去掉（去掉的随即回收），给别的文件 ID 即 <code>SETTINGS_VALIDATION_012</code></td></tr><tr><td><code>POST /api/site/assets/{slot}</code></td><td><code>settings.site.update</code></td><td>换掉 <code>logo</code> 或 <code>favicon</code>：按文件头认 PNG、JPEG、WebP 与 ICO（不认 SVG），不超过 2 MB，否则 <code>SETTINGS_VALIDATION_013</code>；旧图回收</td></tr><tr><td><code>site.resolve</code>（<code>GET /api/site:resolve?host=</code>）</td><td>匿名</td><td>前端壳层用：登录了按令牌里的租户，没登录按 <code>host</code> 找绑定了这个域名的租户，返回生效的设置（租户的叠在平台的之上）与按域名找到的租户 ID</td></tr><tr><td><code>GET /api/site/assets/{id}</code></td><td>匿名</td><td>读站点图片（登录页在登录之前就要显示），只认经上面的端点上传的文件，按不可变内容缓存一年</td></tr></tbody></table><p>邮件、短信与机器人消息模板里的变量 <code>brand</code> 调用方没传时，取发送这一侧生效的系统名（经 Contracts 的 <code>ISiteBrand</code>），租户发出的消息即带它自己的品牌。</p><p>图片与头像一样存平台侧、公开级别，不计入租户的存储配额。按域名识别租户（<code>SysTenant.domain</code>，平台在租户编辑里填）只用于登录页展示品牌与预填租户框，不参与身份判定：租户仍只从令牌声明解析。套餐按包放行，基础版及以上的租户才能改自己的品牌。</p><h2 id="用户设置" tabindex="-1">用户设置 <a class="header-anchor" href="#用户设置" aria-label="Permalink to “用户设置”">​</a></h2><p>个人偏好不在 Settings，而在 Identity 的 <code>SysUserSetting</code>（用户 × 场景 <code>Preference</code> / <code>Page</code> × 键，值是 JSON）：<code>user-settings.get</code> / <code>update</code>（只要求登录）。壳层的偏好、收藏、列表的条件预设与列设置、工作台看板布局都存在这里，改了经 <code>UserSettingChanged</code> 推到同一用户的其他设备。</p><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to “页面”">​</a></h2><p><code>src/modules/settings</code>：参数配置（租户行可「覆盖此参数」）、字典（主从两栏）、业务编号（预览与发号记录）、站点设置（平台改站点设置，租户改自己的品牌，没填的项以灰字显示沿用的平台值）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./../configuration">配置参考</a> · <a href="./messaging">消息通知</a> · <a href="./access-policy">访问策略与权限条件</a></li></ul>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};